design.css:
/* Frost — the MKissa look (docs/theme-references/mkissa.md): pure black, Inter, 12 px cards on dark panels, orange ranks. */

/* The side rail: icon over a small label, 8 px hover tiles. */
[data-slot="nav.side"] [data-part="nav.item"] { flex-direction: column; justify-content: center; gap: 3px; min-height: 58px; border-radius: 8px; }
[data-slot="nav.side"] [data-part="nav.item.label"] { opacity: 1 !important; max-width: 60px; font-size: 9px; font-weight: 500; line-height: 1.1; text-align: center; white-space: normal; }
/* Desktop: clear the window's title strip. */
@media (min-width: 641px) { [data-slot="home"] { padding-top: 44px; } }
[data-slot="nav.side"] [data-part="nav.item"][data-active] { color: #ff8112; }

/* Headings and the segmented Latest Updates / New Series strip. */
[data-part="row.title"], [data-part="block.title"] { font-size: 18px; font-weight: 700; color: #ddd; }
[data-slot="block.tabbed-grid"] [data-part="tabs"] { gap: 0; padding: 3px; border: 1px solid #343a40; border-radius: 10px; background: rgba(33, 33, 37, 0.9); width: fit-content; }
[data-slot="block.tabbed-grid"] [data-part="tab"] { padding: 7px 14px; border-radius: 8px; background: transparent; color: rgba(255, 255, 255, 0.5); font-size: 14px; font-weight: 500; }
[data-slot="block.tabbed-grid"] [data-part="tab"][data-active] { background: #2e3440; color: #ddd; }
[data-slot="block.tabbed-grid"] [data-part="tab"] > span { display: none; }

/* Media cards: a status dot before the title, a grey subtitle, a panel footer with a blue accent bar. */
[data-part="frost.poster"] { background: #252a2a; }
[data-part="frost.airing"], [data-part="frost.dot"] { flex: 0 0 6px; width: 6px; height: 6px; border-radius: 999px; }
[data-part="frost.airing"] { background: #22c55e; }
[data-part="frost.dot"] { border: 1.5px solid rgba(255, 255, 255, 0.5); }
[data-part="frost.subtitle"] { padding-left: 14px; color: rgba(255, 255, 255, 0.5); }
[data-part="frost.footer"] { position: relative; min-height: 34px; margin-top: 2px; padding: 4px 8px 4px 11px; border: 1px solid #343a40; border-radius: 8px; background: rgba(33, 33, 37, 0.9); overflow: hidden; }
[data-part="frost.footer"]::before { content: ""; position: absolute; left: 0; top: 0; bottom: 0; width: 3px; background: #325d88; }
[data-part="frost.kind"] { color: rgba(255, 255, 255, 0.5); }
[data-part="frost.chevron"] { margin-left: auto; color: rgba(255, 255, 255, 0.5); }

/* Popular: panel cards with an orange rank circle over the cover. */
[data-slot="block.ranked-list"] [data-part="block.item"] { position: relative; padding: 8px; border: 1px solid #343a40; border-radius: 12px; background: rgba(33, 33, 37, 0.9); }
[data-slot="block.ranked-list"] [data-part="block.rank"] { position: absolute; left: 6px; top: 6px; z-index: 1; width: 28px; height: 28px; display: grid; place-items: center; border-radius: 999px; background: rgba(255, 129, 18, 0.78); color: #f1f8ff; font-size: 12px; font-weight: 700; }
[data-slot="block.ranked-list"] [data-part="card.art"] { width: 64px; border-radius: 8px; }
[data-slot="block.ranked-list"] [data-part="card.title"] { font-size: 14px; font-weight: 600; }
[data-slot="block.ranked-list"] [data-part="card.meta"] { display: inline-block; margin-top: 4px; padding: 1.6px 7.2px; border-radius: 999px; background: rgba(37, 42, 44, 0.65); color: rgba(255, 255, 255, 0.5); font-size: 10.9px; font-weight: 600; }
[data-slot="block.ranked-list"] [data-part="tabs"] { padding: 3px; border: 1px solid #343a40; border-radius: 10px; background: rgba(33, 33, 37, 0.9); }
[data-slot="block.ranked-list"] [data-part="tab"][data-active] { background: #2e3440; color: #ddd; }

/* Series page: the banner card, facts as uppercase-label-over-value columns without boxes. */
[data-slot="detail"] [data-part="detail.poster"] { border-radius: 12px; }
[data-part="detail.facts"][data-variant="cards"] [data-part="fact"] { align-items: flex-start; min-width: 0; padding: 0 14px 0 0; background: transparent; text-align: start; }
[data-part="detail.facts"][data-variant="cards"] [data-part="fact.label"] { order: -1; margin: 0 0 3px; color: rgba(255, 255, 255, 0.5); font-size: 10px; font-weight: 700; letter-spacing: 0.6px; text-transform: uppercase; }
[data-part="detail.facts"][data-variant="cards"] [data-part="fact.value"] { font-size: 13px; font-weight: 700; }

/* Phones: Popular becomes a horizontal rail of small cards, as on the site. */
@media (max-width: 640px) {
  [data-slot="block.ranked-list"] > ol { display: flex; gap: 10px; overflow-x: auto; scrollbar-width: none; }
  [data-slot="block.ranked-list"] > ol > li { flex: 0 0 128px; margin: 0 !important; }
  [data-slot="block.ranked-list"] [data-part="block.item"] { height: 100%; flex-direction: column; align-items: stretch; gap: 6px; }
  [data-slot="block.ranked-list"] [data-part="card.art"] { width: 100%; }
  [data-slot="block.ranked-list"] [data-part="card.title"] { font-size: 12.5px; }
}

/* Continue Watching: the site's portrait card (≈202 px, 6 px corners) with the episode on a dark chip,
   an orange progress bar along the bottom and the title in 13 px below. */
[data-part="frost.cw-ep"] { margin: 0 0 12px 8px !important; padding: 2px 6px; border-radius: 4px; background: rgba(0, 0, 0, 0.72); }
[data-part="frost.cw-bar"] { height: 3px !important; background: rgba(0, 0, 0, 0.6) !important; }
[data-part="frost.cw-bar"] > * { background: #ff8112 !important; }
